12	    static int binarySearch(int[] values, int target) {
13	        Objects.requireNonNull(values, "values");
14	
15	        int low = 0;
16	        int high = values.length - 1;
17	
18	        while (low <= high) {
19	            int mid = midpoint(low, high);
20	            int value = values[mid];
21	
22	            if (value == target) {
23	                return mid;
24	            }
25	
26	            if (value < target) {
27	                low = mid + 1;
28	            } else {
29	                high = mid - 1;
30	            }
31	        }
32	
33	        return NOT_FOUND;
34	    }
